internal final class VNGTamRebateDateTest extends RunBase
{
    DialogField dialogRebateId;
    DialogField dialogFromDate;
    DialogField dialogToDate;
    DialogField dialogRebateTransactionType;

    TAMRebateId rebateId;
    FromDate fromDate;
    ToDate toDate;
    TAMRebateDate rebateDateOutsideDateRange;
    TAMRebateTransactionType rebateTransactionType;

    #define.CurrentVersion(1)
    #localmacro.CurrentList
        rebateId,
        fromDate,
        toDate,
        rebateTransactionType
    #endmacro
}

Method.Source:
public boolean unpack(container packedClass)
{
    Version version = RunBase::getVersion(packedClass);
    ;
    switch (version)
    {
        case #CurrentVersion:
            [version,#CurrentList] = packedClass;
            break;
        default:
            return false;
    }

    return true;
}

public Object dialog()
{
    Dialog dialog = super();

    // Set a title for dialog
    dialog.caption( 'Simple Dialog');

    // Add a new field to Dialog
    dialogRebateId = dialog.addField(extendedTypeStr(TAMRebateId));
    dialogFromDate = dialog.addField(extendedTypeStr(FromDate));
    dialogToDate = dialog.addField(extendedTypeStr(ToDate));
    dialogRebateTransactionType = dialog.addField(enumStr(TAMRebateTransactionType));

    return dialog;
}

// Retrieve values from Dialog
public boolean getFromDialog()
{
    rebateId = dialogRebateId.value();
    fromDate = dialogFromDate.value();
    toDate = dialogToDate.value();
    rebateTransactionType = dialogRebateTransactionType.value();

    return super();
}

