public static void main(Args _args)
{
    VNGTamRebateDateTest rebateDateTest = new VNGTamRebateDateTest();

    // Prompt the dialog, if user clicks in OK it returns true
    if (rebateDateTest.prompt())
    {
        rebateDateTest.run();
    }
}
